(390, 44, 393, 'Bài 1: Thương lượng điều khoản hợp đồng', 'Hai bên đàm phán về thời hạn giao hàng và mức phạt vi phạm.', 1, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(391, 44, 394, 'Bài 2: Tranh luận trong cuộc họp', 'Cuộc họp nội bộ bàn về việc có nên rút khỏi một dự án thua lỗ.', 2, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(392, 44, 395, 'Bài 3: Giải trình sự cố với khách hàng', 'Cuộc gặp xin lỗi và giải trình sau khi hệ thống ngừng hoạt động nửa ngày.', 3, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(393, 44, 396, 'Bài 4: Phản biện trong hội thảo', 'Sau bài trình bày, một người tham dự đặt câu hỏi chất vấn về phương pháp nghiên cứu.', 4, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(394, 44, 397, 'Bài 5: Từ chối đề nghị của đối tác', 'Linh phải từ chối yêu cầu giảm giá mà vẫn giữ quan hệ.', 5, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(395, 44, 398, 'Bài 6: Phỏng vấn vị trí quản lý', 'Vòng phỏng vấn cuối cho vị trí trưởng nhóm.', 6, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(396, 44, 399, 'Bài 7: Thông báo tin không thuận cho đối tác', 'Linh phải báo rằng công ty không thể tiếp tục dự án ở giai đoạn hai.', 7, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(397, 44, 400, 'Bài 8: Bàn về cắt giảm ngân sách', 'Cuộc họp nội bộ khi ngân sách bị cắt và phải chọn bỏ hạng mục nào.', 8, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(398, 44, 401, 'Bài 9: Hoà giải bất đồng giữa hai bộ phận', 'Linh đứng giữa dàn xếp mâu thuẫn giữa bộ phận bán hàng và kỹ thuật.', 9, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(399, 44, 402, 'Bài 10: Chất vấn tại cuộc họp cổ đông', 'Cổ đông chất vấn ban lãnh đạo về kết quả kinh doanh sụt giảm.', 10, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(400, 44, 403, 'Bài 11: Phỏng vấn báo chí về sản phẩm mới', 'Phóng viên hỏi về sản phẩm sắp ra mắt và những lo ngại kèm theo.', 11, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(401, 44, 404, 'Bài 12: Bàn giao dự án cho người kế nhiệm', 'Linh chuyển công tác và bàn giao lại toàn bộ dự án.', 12, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(402, 44, 405, 'Bài 13: Thảo luận rủi ro pháp lý', 'Linh trao đổi với bộ phận pháp chế về điều khoản bảo mật trong hợp đồng.', 13, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
(403, 44, 406, 'Bài 14: Thuyết phục nội bộ về khoản đầu tư', 'Linh trình bày đề xuất đầu tư công cụ mới và đối mặt với hoài nghi.', 14, 20, 'CURRICULUM', 'LISTENING', 'FOUNDATION', 0, 'DRAFT'),
