(431, 33, 'GRAMMAR', 41, 'Ví dụ 45', 'ともだちに おかねを ちょっと かります。', 'Tôi mượn một chút tiền từ bạn.', 45),
(432, 33, 'GRAMMAR', 41, 'Ví dụ 46', 'たんじょうびに ともだちに プレゼントを もらいます。', 'Vào sinh nhật, tôi nhận quà từ bạn.', 46),
(433, 33, 'GRAMMAR', 40, 'Ví dụ 47', 'クリスマスに ともだちに プレゼントを あげます。', 'Vào lễ Giáng sinh, tôi tặng quà cho bạn.', 47),
(434, 33, 'GRAMMAR', 40, 'Ví dụ 48', 'こどもに 「ありがとう ございます」を おしえます。', 'Tôi dạy trẻ con câu "Cảm ơn".', 48),
(435, 33, 'GRAMMAR', 40, 'Ví dụ 49', 'こどもに 「どういたしまして」を おしえます。', 'Tôi dạy trẻ con câu "Không có gì".', 49),
(436, 34, 'LISTENING', NULL, 'Tanaka', 'グエンさん、たんじょうびの プレゼントです。', 'Anh Nguyễn, quà sinh nhật cho anh đây.', 1),
(437, 34, 'LISTENING', NULL, 'Nguyễn', 'ありがとう ございます。', 'Cảm ơn anh.', 2),
(438, 34, 'LISTENING', NULL, 'Tanaka', 'どういたしまして。どうりょうも カードを かきました。', 'Không có gì. Mấy đồng nghiệp cũng viết thiệp nữa.', 3),
(439, 34, 'LISTENING', NULL, 'Nguyễn', 'カードも ですか。うれしいです。', 'Có cả thiệp nữa ạ? Tôi vui quá.', 4),
(440, 34, 'LISTENING', NULL, 'Tanaka', 'かぞくには もう でんわで はなしましたか。', 'Anh đã gọi điện nói với gia đình chưa?', 5),
(441, 34, 'LISTENING', NULL, 'Nguyễn', 'まだです。よる はなします。', 'Vẫn chưa. Tối tôi gọi.', 6),
(442, 34, 'LISTENING', NULL, 'Tanaka', 'おかあさんに メールも おくりますか。', 'Anh có gửi cả thư điện tử cho mẹ không?', 7),
(443, 34, 'LISTENING', NULL, 'Nguyễn', 'はい、パソコンで おくります。', 'Có, tôi gửi bằng máy tính.', 8),
(444, 35, 'LISTENING', NULL, 'Linh', 'グエンさん、その じしょは だれに もらいましたか。', 'Anh Nguyễn, quyển từ điển đó anh được ai cho thế?', 1),
(445, 35, 'LISTENING', NULL, 'Nguyễn', 'せんせいに もらいました。', 'Tôi được cô giáo cho.', 2),
(446, 35, 'LISTENING', NULL, 'Linh', 'わたしも かんじを ならいます。', 'Em cũng đang học chữ Hán.', 3),
(447, 35, 'LISTENING', NULL, 'Nguyễn', 'じゃ、この じしょを かします。', 'Vậy tôi cho em mượn quyển này.', 4),
(448, 35, 'LISTENING', NULL, 'Linh', 'ありがとう ございます。かんじは にほんごで ならいますか。', 'Cảm ơn anh. Chữ Hán thì học bằng tiếng Nhật ạ?', 5),
(449, 35, 'LISTENING', NULL, 'Nguyễn', 'いいえ、ベトナムごで ならいます。', 'Không, học bằng tiếng Việt.', 6),
(450, 35, 'LISTENING', NULL, 'Linh', 'ことばは パソコンで かきますか。', 'Từ mới thì anh chép bằng máy tính ạ?', 7),
(451, 35, 'LISTENING', NULL, 'Nguyễn', 'はい。ときどき たなかさんに ならいます。', 'Ừ. Thỉnh thoảng tôi học thêm từ anh Tanaka.', 8),
