(977, 74, 'LISTENING', NULL, 'Nguyễn', 'にもつを もって はいっても いいですか。', 'Tôi mang túi vào được không?', 5),
(978, 74, 'LISTENING', NULL, 'Linh', 'ちょっと むずかしいです。', 'Cái đó thì hơi khó ạ.', 6),
(979, 74, 'LISTENING', NULL, 'Nguyễn', 'わかりました。ここで まちます。', 'Tôi hiểu rồi. Tôi đợi ở đây.', 7),
(980, 74, 'LISTENING', NULL, 'Linh', 'どうぞ、そこに すわって ください。', 'Mời anh ngồi ở đó.', 8),
(981, 75, 'LISTENING', NULL, 'Tanaka', 'グエンさんは どこに すんで いますか。', 'Anh Nguyễn sống ở đâu?', 1),
(982, 75, 'LISTENING', NULL, 'Nguyễn', 'とうきょうの ちかくに すんで います。', 'Tôi sống gần Tokyo.', 2),
(983, 75, 'LISTENING', NULL, 'Tanaka', 'ひとりで すんで いますか。', 'Anh sống một mình à?', 3),
(984, 75, 'LISTENING', NULL, 'Nguyễn', 'ええ。かぞくは ベトナムに います。', 'Ừ. Gia đình tôi ở Việt Nam.', 4),
(985, 75, 'LISTENING', NULL, 'Tanaka', 'おにいさんも いますか。', 'Anh có anh trai không?', 5),
(986, 75, 'LISTENING', NULL, 'Nguyễn', 'はい。あには ぎんこうに つとめて います。', 'Có. Anh tôi làm ở ngân hàng.', 6),
(987, 75, 'LISTENING', NULL, 'Tanaka', 'けっこんして いますか。', 'Anh ấy lập gia đình chưa?', 7),
(988, 75, 'LISTENING', NULL, 'Nguyễn', 'あには けっこんして います。わたしは まだです。', 'Anh tôi có rồi. Còn tôi thì chưa.', 8),
(989, 76, 'READING', NULL, 'Danh sách từ vựng bài 16', 'Bài 16 có 51 từ vựng.', NULL, 1),
