(1602, 123, 'GRAMMAR', 129, 'Ví dụ 3', 'やすかったら、りょこうに いきます。', 'Nếu rẻ, tôi sẽ đi du lịch.', 3),
(1603, 123, 'GRAMMAR', 129, 'Ví dụ 4', 'じかんが あったら、あそびに いきます。', 'Nếu có thời gian, tôi sẽ đi chơi.', 4),
(1604, 123, 'GRAMMAR', 129, 'Ví dụ 5', 'つかれたら、うちに います。', 'Nếu mệt, tôi sẽ ở nhà.', 5),
(1605, 123, 'GRAMMAR', 129, 'Ví dụ 6', 'わからなかったら、きいて ください。', 'Nếu không hiểu thì anh hỏi nhé.', 6),
