(1617, 123, 'GRAMMAR', 131, 'Ví dụ 18', 'らいげつ、ひっこします。', 'Tháng sau, tôi sẽ chuyển nhà.', 18),
(1618, 123, 'GRAMMAR', 131, 'Ví dụ 19', 'らいねん、くにへ かえります。', 'Sang năm, tôi sẽ về nước.', 19),
(1619, 123, 'GRAMMAR', 131, 'Ví dụ 20', 'らいげつ けっこんしますから、ひっこします。', 'Vì tháng sau lập gia đình nên tôi sẽ chuyển nhà.', 20),
(1620, 123, 'GRAMMAR', 130, 'Ví dụ 21', 'たいへんでも、べんきょうを つづけます。', 'Dù vất vả, tôi vẫn tiếp tục học.', 21),
(1621, 123, 'GRAMMAR', 131, 'Ví dụ 22', 'らいねん、ひっこします。', 'Sang năm, tôi sẽ chuyển nhà.', 22),
(1622, 123, 'GRAMMAR', 131, 'Ví dụ 23', 'らいげつ、しごとを かえます。', 'Tháng sau, tôi sẽ đổi công việc.', 23),
