(1686, 128, 'GRAMMAR', 134, 'Ví dụ 20', 'じゅうしょを かえるんです。', 'Tôi đổi địa chỉ.', 20),
(1687, 128, 'GRAMMAR', 138, 'Ví dụ 21', 'これを コピーしたら いいですか。', 'Photo cái này là được phải không ạ?', 21),
(1688, 128, 'GRAMMAR', 136, 'Ví dụ 22', 'びょういんへ いきたいんです。', 'Tôi muốn đi đến bệnh viện.', 22),
