(2501, 188, 'GRAMMAR', 210, 'Ví dụ 28', 'ほんを よむのは おもしろいですか。', 'Đọc sách có thú vị không?', 28),
(2502, 188, 'GRAMMAR', 210, 'Ví dụ 29', 'えを かくのは かんたんですか。', 'Vẽ tranh có dễ không?', 29),
(2503, 188, 'GRAMMAR', 210, 'Ví dụ 30', 'かんじを おぼえるのは むずかしいですか。', 'Ghi nhớ chữ Hán có khó không?', 30),
(2504, 188, 'GRAMMAR', 210, 'Ví dụ 31', 'はやく おきるのは たいへんですか。', 'Dậy sớm có vất không?', 31),
(2505, 188, 'GRAMMAR', 210, 'Ví dụ 32', 'レポートを かくのは むずかしいですか。', 'Viết báo cáo có khó không?', 32),
(2506, 188, 'GRAMMAR', 209, 'Ví dụ 33', 'かぎを かけるのを わすれました。', 'Tôi quên khoá cửa.', 33),
(2507, 188, 'GRAMMAR', 209, 'Ví dụ 34', 'でんきを けすのを わすれました。', 'Tôi quên tắt đèn.', 34),
