(2510, 188, 'GRAMMAR', 209, 'Ví dụ 37', 'かぎを もつのを わすれました。', 'Tôi đã quên mang theo chìa khoá.', 37),
(2511, 188, 'GRAMMAR', 205, 'Ví dụ 38', 'バスを まつのが きらいです。', 'Tôi ghét phải chờ xe buýt.', 38),
(2512, 188, 'GRAMMAR', 205, 'Ví dụ 39', 'はなすのが すきです。', 'Tôi thích nói chuyện.', 39),
(2513, 188, 'GRAMMAR', 205, 'Ví dụ 40', 'あるくのが すきです。', 'Tôi thích đi bộ.', 40),
(2514, 188, 'GRAMMAR', 207, 'Ví dụ 41', 'ひとりで およぐのは さびしいです。', 'Bơi một mình thì buồn.', 41),
(2515, 188, 'GRAMMAR', 207, 'Ví dụ 42', 'みんなで うたうのは たのしいです。', 'Cả nhóm cùng hát thì vui.', 42),
(2516, 188, 'GRAMMAR', 208, 'Ví dụ 43', 'はじめて ひとりで およぐ ことが できました。', 'Lần đầu tiên tôi tự bơi được một mình.', 43),
(2517, 188, 'GRAMMAR', 208, 'Ví dụ 44', 'たいせつな ことは そのことを れんらくする ことです。', 'Điều quan trọng là báo tin về chuyện đó.', 44),
(2518, 188, 'GRAMMAR', 210, 'Ví dụ 45', 'しゅみは なにを する ことですか。', 'Sở thích của anh là làm gì ạ?', 45),
(2519, 188, 'GRAMMAR', 210, 'Ví dụ 46', 'ゆめは どんな ことですか。', 'Ước mơ của anh là gì ạ?', 46),
(2520, 188, 'GRAMMAR', 210, 'Ví dụ 47', 'うたうのと はしるのは どちらが たのしいですか。', 'Hát và chạy bộ thì bên nào vui hơn?', 47),
(2521, 188, 'GRAMMAR', 207, 'Ví dụ 48', 'ひとりで たべるのは さびしいです。', 'Ăn một mình thì buồn.', 48),
(2522, 188, 'GRAMMAR', 205, 'Ví dụ 49', 'たべるのが すきです。', 'Tôi thích ăn.', 49),
(2523, 188, 'GRAMMAR', 208, 'Ví dụ 50', 'ゆめは えを かく ことです。', 'Ước mơ là việc vẽ tranh.', 50),
(2524, 189, 'LISTENING', NULL, 'Tanaka', 'しゅみは なにを する ことですか。', 'Sở thích của em là làm gì?', 1),
(2525, 189, 'LISTENING', NULL, 'Linh', 'しゅみは しゃしんを とる ことです。', 'Sở thích của em là chụp ảnh ạ.', 2),
(2526, 189, 'LISTENING', NULL, 'Tanaka', 'いいですね。えを かくのは とくいですか。', 'Hay nhỉ. Em có khá khoản vẽ không?', 3),
(2527, 189, 'LISTENING', NULL, 'Linh', 'えを かくのは へたです。でも みるのは すきです。', 'Vẽ thì em vụng ạ. Nhưng xem thì em thích.', 4),
(2528, 189, 'LISTENING', NULL, 'Tanaka', 'りょうりは どうですか。', 'Nấu ăn thì sao?', 5),
(2529, 189, 'LISTENING', NULL, 'Linh', 'りょうりするのが とくいです。みんなで つくるのは たのしいです。', 'Nấu ăn thì em khá. Cả nhóm cùng làm thì vui ạ.', 6),
(2530, 189, 'LISTENING', NULL, 'Tanaka', 'ゆめは どんな ことですか。', 'Ước mơ của em là gì?', 7),
(2531, 189, 'LISTENING', NULL, 'Linh', 'ゆめは にほんで はたらく ことです。', 'Ước mơ của em là làm việc ở Nhật ạ.', 8),
(2532, 190, 'LISTENING', NULL, 'Nguyễn', 'あ、かぎを かけるのを わすれました。', 'À, tôi quên khoá cửa mất rồi.', 1),
(2533, 190, 'LISTENING', NULL, 'Tanaka', 'でんきは けしましたか。', 'Đèn tắt chưa?', 2),
(2534, 190, 'LISTENING', NULL, 'Nguyễn', 'でんきを けすのも わすれました。', 'Tắt đèn tôi cũng quên nốt.', 3),
(2535, 190, 'LISTENING', NULL, 'Tanaka', 'しょるいは だしましたか。', 'Giấy tờ nộp chưa?', 4),
(2536, 190, 'LISTENING', NULL, 'Nguyễn', 'しょるいを だすのを わすれました。いま だします。', 'Giấy tờ tôi quên nộp. Để tôi nộp ngay.', 5),
(2537, 190, 'LISTENING', NULL, 'Tanaka', 'レポートを かくのは じかんが かかりますか。', 'Viết báo cáo có mất thời gian không?', 6),
(2538, 190, 'LISTENING', NULL, 'Nguyễn', 'レポートを かくのは じかんが かかります。でも たのしいです。', 'Viết báo cáo thì mất thời gian. Nhưng vui.', 7),
(2539, 190, 'LISTENING', NULL, 'Tanaka', 'たいせつな ことは まいにち つづける ことですよ。', 'Điều quan trọng là ngày nào cũng làm tiếp đấy.', 8),
(2540, 191, 'READING', NULL, 'Danh sách từ vựng bài 39', 'Bài 39 có 50 từ vựng.', NULL, 1),
(2541, 193, 'GRAMMAR', 211, 'Ví dụ 1', 'でんしゃが おくれて、ちこくしました。', 'Tàu điện trễ nên tôi tới muộn.', 1),
(2542, 193, 'GRAMMAR', 211, 'Ví dụ 2', 'みちが こんで、ちこくしました。', 'Đường tắc nên tôi đã đến muộn.', 2),
(2543, 193, 'GRAMMAR', 211, 'Ví dụ 3', 'ねつが でて、がっこうを やすみました。', 'Tôi sốt nên nghỉ học.', 3),
(2544, 193, 'GRAMMAR', 211, 'Ví dụ 4', 'ようじが あって、ちこくしました。', 'Có việc bận nên tôi đã đến muộn.', 4),
(2545, 193, 'GRAMMAR', 211, 'Ví dụ 5', 'じこが あって、でんしゃが とまりました。', 'Có tai nạn nên tàu điện đã dừng.', 5),
(2546, 193, 'GRAMMAR', 211, 'Ví dụ 6', 'みちに まよって、ちこくしました。', 'Vì lạc đường nên tôi đã đến muộn.', 6),
(2547, 193, 'GRAMMAR', 212, 'Ví dụ 7', 'しごとが おおくて、こまりました。', 'Công việc nhiều nên tôi đã gặp khó khăn.', 7),
(2548, 193, 'GRAMMAR', 213, 'Ví dụ 8', 'パソコンが なおって、うれしかったです。', 'Vì máy tính đã được sửa xong nên tôi rất vui.', 8),
(2549, 193, 'GRAMMAR', 213, 'Ví dụ 9', 'きゅうに よばれて、びっくりしました。', 'Bị gọi đột ngột nên tôi giật mình.', 9),
(2550, 193, 'GRAMMAR', 213, 'Ví dụ 10', 'れんらくが きて、あんしんしました。', 'Có tin báo nên tôi yên tâm.', 10),
(2551, 193, 'GRAMMAR', 212, 'Ví dụ 11', 'とおくて、ざんねんでした。', 'Xa quá nên thật đáng tiếc.', 11),
(2552, 193, 'GRAMMAR', 212, 'Ví dụ 12', 'ひとが おおくて、はずかしかったです。', 'Đông người nên tôi đã thấy ngượng.', 12),
(2553, 193, 'GRAMMAR', 212, 'Ví dụ 13', 'とおくて、しんぱいしました。', 'Xa quá nên tôi đã lo lắng.', 13),
(2554, 193, 'GRAMMAR', 213, 'Ví dụ 14', 'ごうかくして、うれしかったです。', 'Thi đỗ nên tôi đã rất vui.', 14),
(2555, 193, 'GRAMMAR', 213, 'Ví dụ 15', 'プレゼントが とどいて、うれしかったです。', 'Quà tới nơi nên tôi rất vui.', 15),
(2556, 193, 'GRAMMAR', 213, 'Ví dụ 16', 'ひさしぶりに あって、うれしかったです。', 'Lâu ngày gặp lại nên tôi đã rất vui.', 16),
(2557, 193, 'GRAMMAR', 213, 'Ví dụ 17', 'ほめられて、うれしかったです。', 'Được khen nên tôi đã rất vui.', 17),
(2558, 193, 'GRAMMAR', 211, 'Ví dụ 18', 'みちに まよって、こまりました。', 'Tôi lạc đường nên khổ sở.', 18),
(2559, 193, 'GRAMMAR', 211, 'Ví dụ 19', 'ともだちと けんかして、かなしかったです。', 'Tôi cãi nhau với bạn nên thấy buồn.', 19),
(2560, 193, 'GRAMMAR', 214, 'Ví dụ 20', 'じしんで こわれて、こまりました。', 'Vì động đất nên bị hỏng, tôi gặp rắc rối.', 20),
(2561, 193, 'GRAMMAR', 214, 'Ví dụ 21', 'でんしゃで パソコンを なくして、こまりました。', 'Tôi đánh mất máy tính trên tàu nên khổ.', 21),
(2562, 193, 'GRAMMAR', 214, 'Ví dụ 22', 'あめで がっこうが やすみに なりました。', 'Vì mưa nên trường học thành ngày nghỉ.', 22),
