(3291, 248, 'GRAMMAR', 278, 'Ví dụ 10', 'おちゃを いただきます。', 'Tôi xin dùng trà ạ.', 10),
(3292, 248, 'GRAMMAR', 278, 'Ví dụ 11', 'しりょうを はいけんします。', 'Tôi xin phép xem tài liệu ạ.', 11),
(3293, 248, 'GRAMMAR', 280, 'Ví dụ 12', 'けっかは ぞんじて おります。', 'Về kết quả thì tôi có biết ạ.', 12),
(3294, 248, 'GRAMMAR', 279, 'Ví dụ 13', 'わたくしは グエンと もうします。', 'Tôi tên là Nguyen ạ.', 13),
(3295, 248, 'GRAMMAR', 279, 'Ví dụ 14', 'わたくしは かいはつぶの たなかと もうします。', 'Tôi là Tanaka ở phòng phát triển ạ.', 14),
(3296, 248, 'GRAMMAR', 279, 'Ví dụ 15', 'はじめまして、わたくしは たなかと もうします。', 'Hân hạnh gặp ngài, tôi tên là Tanaka ạ.', 15),
(3297, 248, 'GRAMMAR', 278, 'Ví dụ 16', 'はじめまして、よろしく おねがい いたします。', 'Hân hạnh được gặp ngài, mong được ngài giúp đỡ ạ.', 16),
(3298, 248, 'GRAMMAR', 279, 'Ví dụ 17', 'わたくしは ベトナムしゅっしんの グエンと もうします。', 'Tôi là Nguyen, quê quán ở Việt Nam ạ.', 17),
(3299, 248, 'GRAMMAR', 280, 'Ví dụ 18', 'たなかは ただいま せきを はずして おります。', 'Anh Tanaka hiện không có mặt ạ.', 18),
(3300, 248, 'GRAMMAR', 280, 'Ví dụ 19', 'たなかは くうこうへ でかけて おります。', 'Anh Tanaka đang đi vắng tới sân bay rồi ạ.', 19),
(3301, 248, 'GRAMMAR', 280, 'Ví dụ 20', 'かいぎしつで まって おります。', 'Tôi đang chờ ở phòng họp ạ.', 20),
(3302, 248, 'GRAMMAR', 280, 'Ví dụ 21', 'ただいま しりょうを つくって おります。', 'Hiện tôi đang làm tài liệu ạ.', 21),
(3303, 248, 'GRAMMAR', 277, 'Ví dụ 22', 'かいぎしつまで ごあんないします。', 'Tôi xin phép dẫn đường đến phòng họp ạ.', 22),
(3304, 248, 'GRAMMAR', 277, 'Ví dụ 23', 'わたくしが おちゃを おとりします。', 'Tôi xin phép lấy trà giúp ạ.', 23),
(3305, 248, 'GRAMMAR', 281, 'Ví dụ 24', 'けっかを せつめいさせて いただきます。', 'Tôi xin phép được giải thích về kết quả ạ.', 24),
(3306, 248, 'GRAMMAR', 281, 'Ví dụ 25', 'さきに はっぴょうさせて いただきます。', 'Tôi xin phép được trình bày trước ạ.', 25),
(3307, 248, 'GRAMMAR', 281, 'Ví dụ 26', 'あした やすませて いただきます。', 'Ngày mai tôi xin phép được nghỉ ạ.', 26),
(3308, 248, 'GRAMMAR', 281, 'Ví dụ 27', 'さきに かえらせて いただきます。', 'Tôi xin phép được về trước ạ.', 27),
(3309, 248, 'GRAMMAR', 281, 'Ví dụ 28', 'この かさを つかわせて いただきます。', 'Tôi xin phép được dùng cái ô này ạ.', 28),
(3310, 248, 'GRAMMAR', 282, 'Ví dụ 29', 'にもつは おもちしましょうか。', 'Hành lý để tôi mang nhé ạ?', 29),
(3311, 248, 'GRAMMAR', 282, 'Ví dụ 30', 'メールは とどきましたか。', 'Thư điện tử đã tới chưa ạ?', 30),
(3312, 248, 'GRAMMAR', 282, 'Ví dụ 31', 'かいぎしつは どちらですか。', 'Phòng họp ở đâu ạ?', 31),
(3313, 248, 'GRAMMAR', 282, 'Ví dụ 32', 'たなかさんは いらっしゃいますか。', 'Anh Tanaka có ở đó không ạ?', 32),
(3314, 248, 'GRAMMAR', 282, 'Ví dụ 33', 'くうこうへは なんじに まいれば よろしいですか。', 'Mấy giờ tôi ra sân bay thì được ạ?', 33),
(3315, 248, 'GRAMMAR', 282, 'Ví dụ 34', 'コピーは おねがいできますか。', 'Nhờ anh phô tô được không ạ?', 34),
(3316, 248, 'GRAMMAR', 277, 'Ví dụ 35', 'かいぎしつまで しりょうを おもちします。', 'Tôi xin phép mang tài liệu đến phòng họp ạ.', 35),
(3317, 248, 'GRAMMAR', 280, 'Ví dụ 36', 'たなかは まって おります。', 'Anh Tanaka đang chờ ạ.', 36),
(3318, 248, 'GRAMMAR', 278, 'Ví dụ 37', 'ただいま くうこうへ まいります。', 'Ngay lúc này tôi sẽ tới sân bay ạ.', 37),
(3319, 248, 'GRAMMAR', 277, 'Ví dụ 38', 'わたくしが コピーを おもちします。', 'Tôi xin phép mang bản phô tô đến ạ.', 38),
(3320, 248, 'GRAMMAR', 280, 'Ví dụ 39', 'ただいま かいぎしつで まって おります。', 'Tôi hiện đang chờ ở phòng họp ạ.', 39),
(3321, 248, 'GRAMMAR', 278, 'Ví dụ 40', 'のちほど おたくへ まいります。', 'Lát nữa tôi sẽ tới quý phủ ạ.', 40),
(3322, 248, 'GRAMMAR', 281, 'Ví dụ 41', 'さきに つかわせて いただきます。', 'Tôi xin phép được dùng trước ạ.', 41),
