(3324, 248, 'GRAMMAR', 277, 'Ví dụ 43', 'のちほど おでんわを おかけします。', 'Tôi xin phép gọi điện thoại sau ạ.', 43),
(3325, 248, 'GRAMMAR', 277, 'Ví dụ 44', 'メールを おおくりします。', 'Tôi xin gửi thư điện tử ạ.', 44),
(3326, 248, 'GRAMMAR', 277, 'Ví dụ 45', 'さきに メールを おおくりします。', 'Tôi xin phép gửi thư điện tử trước ạ.', 45),
(3327, 248, 'GRAMMAR', 278, 'Ví dụ 46', 'しりょうを おねがい いたします。', 'Tôi xin nhờ ngài việc tài liệu ạ.', 46),
